import importlib.util
spec = importlib.util.spec_from_file_location('m','/app/main.py')
m = importlib.util.module_from_spec(spec)
spec.loader.exec_module(m)
board, unrev, err = m.load_board()
print('err',err, 'unrev', len(unrev))
constraints=[]
for r in range(16):
 for c in range(16):
  v=board[r][c]
  if v!='.':
   neigh=[]
   for dr in (-1,0,1):
    for dc in (-1,0,1):
     if dr==0 and dc==0: continue
     nr,nc=r+dr,c+dc
     if 0<=nr<16 and 0<=nc<16 and board[nr][nc]=='.':
      neigh.append((nr,nc))
   if neigh:
    constraints.append((neigh,int(v)))
print('constraints',len(constraints))
comps = m.split_components(constraints)
print('ncomps',len(comps))
for i,(ccells,ccons) in enumerate(comps):
 print(f"comp{i}: ncells={len(ccells)} ncons={len(ccons)}")
 print(' cells',sorted(ccells))
 for neigh,req in ccons:
  print('  ',req, sorted(neigh))
